MERGE `{{params.project_name}}.semantics_central.Places` final
USING (
{{range_query}}
) staging
ON final.place_id = staging.place_id
WHEN MATCHED THEN
UPDATE SET
final.country_id = staging.country_id,
final.city = staging.city,
final.place_location = staging.place_location,
final.place = staging.place,
final.bi_mapping = staging.bi_mapping,
final.address1 = staging.address1,
final.address2 = staging.address2,
final.zipcode = staging.zipcode,
final.timezone = staging.timezone,
final.timezone_offset = staging.timezone_offset,
final.lat = staging.lat,
final.lon = staging.lon,
final.is_active = staging.is_active,
final.is_inspection_center = staging.is_inspection_center,
final.is_purchase_location = staging.is_purchase_location,
final.is_selling_location = staging.is_selling_location,
final.is_current_location = staging.is_current_location,
final.is_document_location = staging.is_document_location,
final.is_pickup_location = staging.is_pickup_location,
final.inspection_center_id = staging.inspection_center_id,
final.region = staging.region,
final.meta_info = staging.meta_info,
final.place_created = staging.place_created,
final.place_last_modified = staging.place_last_modified,
final.deleted_at = staging.deleted_at
WHEN NOT MATCHED THEN
INSERT (
place_id,
country_id,
city,
place_location,
place,
bi_mapping,
address1,
address2,
zipcode,
timezone,
timezone_offset,
lat,
lon,
is_active,
is_inspection_center,
is_purchase_location,
is_selling_location,
is_current_location,
is_document_location,
is_pickup_location,
inspection_center_id,
region,
meta_info,
place_created,
place_last_modified,
deleted_at
) VALUES (
staging.place_id,
staging.country_id,
staging.city,
staging.place_location,
staging.place,
staging.bi_mapping,
staging.address1,
staging.address2,
staging.zipcode,
staging.timezone,
staging.timezone_offset,
staging.lat,
staging.lon,
staging.is_active,
staging.is_inspection_center,
staging.is_purchase_location,
staging.is_selling_location,
staging.is_current_location,
staging.is_document_location,
staging.is_pickup_location,
staging.inspection_center_id,
staging.region,
staging.meta_info,
staging.place_created,
staging.place_last_modified,
staging.deleted_at
)